<?php
header('Content-Type: application/json');
require_once __DIR__.'/../config/response.php'; require_once __DIR__.'/../config/db.php'; require_once __DIR__.'/../auth/auth_required.php'; require_once __DIR__.'/../auth/role_helper.php'; require_once __DIR__.'/service.php';
try { if($_SERVER['REQUEST_METHOD']!=='GET')jsonResponse(['success'=>false,'message'=>'Method not allowed'],405); $uid=(int)requireAuth()->id;$id=(int)($_GET['invoice_id']??0);$c=db();requireAnyPermission($c,$uid,['invoices.view','payments.view','withholding.view']);$summary=settlementSummary($c,$id,$uid);
$canViewPayments=userHasPermission($c,$uid,'payments.view');$canViewWithholding=userHasPermission($c,$uid,'withholding.view');$payments=[];$withholdings=[];
if($canViewPayments){$s=$c->prepare("SELECT p.id,p.amount,p.exchange_rate,p.exchange_rate_date,p.amount_tnd,p.payment_date,p.method,p.account_name,p.reference_number,p.status,p.voided_at,p.void_reason,p.created_at,u.email recorded_by_name,(p.proof_path IS NOT NULL) has_attachment FROM erp_invoice_payments p LEFT JOIN users u ON u.id=p.recorded_by WHERE p.invoice_id=? AND p.user_id=? ORDER BY p.payment_date DESC,p.id DESC");$s->bind_param('ii',$id,$uid);$s->execute();$payments=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}
if($canViewWithholding){$s=$c->prepare("SELECT w.id,w.withholding_type,w.rate,w.calculation_base,w.withheld_amount,w.certificate_number,w.certificate_date,w.expected_certificate_date,w.certificate_status,w.received_at,w.validated_at,w.cancelled_at,w.validation_notes,w.created_at,w.updated_at,u.email recorded_by_name,(w.attachment_path IS NOT NULL) has_attachment FROM erp_invoice_withholdings w LEFT JOIN users u ON u.id=w.recorded_by WHERE w.invoice_id=? AND w.user_id=? ORDER BY w.id DESC");$s->bind_param('ii',$id,$uid);$s->execute();$withholdings=$s->get_result()->fetch_all(MYSQLI_ASSOC);$s->close();}jsonResponse(['success'=>true,'summary'=>$summary,'payments'=>$payments,'withholdings'=>$withholdings,'access'=>['payments'=>$canViewPayments,'withholding'=>$canViewWithholding]]);
}catch(Throwable $e){jsonResponse(['success'=>false,'message'=>$e->getMessage()],resourceExceptionStatus($e));}
